/**
 * @param {string} str
 * @return {null|boolean|number|string|Array|Object}
 */
var jsonParse = function(str) {
    let i = 0;   // shared cursor, advanced by every helper

    function parseValue() {
        const ch = str[i];
        if (ch === '"') return parseString();
        if (ch === '{') return parseObject();
        if (ch === '[') return parseArray();
        if (ch === 't') { i += 4; return true; }    // "true"
        if (ch === 'f') { i += 5; return false; }   // "false"
        if (ch === 'n') { i += 4; return null; }    // "null"
        return parseNumber();
    }

    function parseString() {
        i++;                                // skip opening quote
        const start = i;
        while (str[i] !== '"') i++;         // no escapes per the statement
        const value = str.slice(start, i);
        i++;                                // skip closing quote
        return value;
    }

    function parseNumber() {
        const start = i;
        // digits, sign, decimal point and exponent characters
        while (i < str.length && /[-+0-9.eE]/.test(str[i])) i++;
        return Number(str.slice(start, i));
    }

    function parseArray() {
        const arr = [];
        i++;                                // skip [
        while (str[i] !== ']') {
            arr.push(parseValue());
            if (str[i] === ',') i++;        // skip comma between elements
        }
        i++;                                // skip ]
        return arr;
    }

    function parseObject() {
        const obj = {};
        i++;                                // skip {
        while (str[i] !== '}') {
            const key = parseString();
            i++;                            // skip :
            obj[key] = parseValue();
            if (str[i] === ',') i++;        // skip comma between pairs
        }
        i++;                                // skip }
        return obj;
    }

    return parseValue();
};
